<?php
namespace App\Livewire\LMS\Lessons\Admin;
use App\Livewire\LMS\Lessons\Concerns\ManagesLessons; use App\Models\{Lesson,Topic}; use Illuminate\Database\Eloquent\Builder; use Livewire\Attributes\Layout;
#[Layout('layouts.lms')] class Index extends ManagesLessons { public function mount():void{$this->authorize('viewAny',Lesson::class);abort_unless(auth()->user()->hasAnyRole(['super_admin','school_admin']),403);} protected function topics():Builder{return Topic::with(['classSubject.schoolClass','classSubject.subject','classSubject.teacher'])->whereHas('classSubject.schoolClass.academicYear',fn(Builder $query)=>$query->where('school_id',$this->schoolId()))->orderBy('sequence');} protected function teacherIdFor(array $data,Topic $topic):int{$teacherId=filled($data['teacherId'])?(int)$data['teacherId']:$topic->classSubject->teacher_id;abort_unless($teacherId,422,'Assign a responsible teacher before creating this lesson.');return $teacherId;} protected function componentView():string{return 'livewire.lms.lessons.admin.index';} }
